import{R as e,e as o,f as a,U as r}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Loqate","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/address-providers/loqate.md","filePath":"integrations/address-providers/loqate.md","lastUpdated":1775908585000}'),n={name:"integrations/address-providers/loqate.md"};function i(s,t,l,d,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="loqate" tabindex="-1">Loqate <a class="header-anchor" href="#loqate" aria-label="Permalink to &quot;Loqate&quot;">​</a></h1><p>Use <a href="https://account.loqate.com/" target="_blank" rel="noreferrer">Loqate</a> to use their service to suggest addresses.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Address Providers</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Loqate as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-loqate-api" tabindex="-1">Step 2. Connect to the Loqate API <a class="header-anchor" href="#step-2-connect-to-the-loqate-api" aria-label="Permalink to &quot;Step 2. Connect to the Loqate API&quot;">​</a></h3><ol><li>Login to your <a href="https://account.loqate.com" target="_blank">Loqate</a> account.</li><li>Click the <strong>Add Service</strong> button in the header.</li><li>Click <strong>API Key</strong> from the provided panes.</li><li>Copy the <strong>API Key</strong> and enter this in the <strong>API Key</strong> field in Formie.</li></ol><h3 id="step-3-field-setting" tabindex="-1">Step 3. Field Setting <a class="header-anchor" href="#step-3-field-setting" aria-label="Permalink to &quot;Step 3. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add an <strong>Address</strong> field to your form.</li><li>Enable the <strong>Auto-Complete</strong> sub-field option.</li><li>Select Loqate for the <strong>Auto-Complete Integration</strong>.</li></ol><p>You can also provide <a href="https://www.loqate.com/resources/support/setup-guides/advanced-setup-guide/#setting_options" target="_blank" rel="noreferrer">Widget Options</a> in the table field. The <code>value</code> content must be valid JSON, so ensure you encase strings in <code>&quot;</code> characters. For example, the below might return the location (street, suburb and city) results.</p><table tabindex="0"><thead><tr><th>Option</th><th>Value</th></tr></thead><tbody><tr><td><code>show_locations</code></td><td><code>true</code></td></tr></tbody></table>',10)])])}const u=e(n,[["render",i]]);export{p as __pageData,u as default};
